// lib/utils/invite-code.ts
export function generateInviteCode(): string { return crypto.randomUUID().replace(/-/g, '').slice(0, 8); }

// lib/utils/event-status.ts
export function computeEventStatus(eventDate: string): EventStatus { compare Date.now() vs eventDate, return 'upcoming' | 'ongoing' | 'completed' }

